def ut(id_, title, prio, trace, test, goal, checks, c1="Đạt (tự động)", **kw):
    return {
        "id": id_, "title": title, "prio": prio, "trace": trace, "mode": "cli", "c1": c1,
        "auto": f"`{test}`" if test else "– (cần viết)", "goal": goal,
        "pre": [VENV, EVIDENCE, APP + " (để ghi bản build đang kiểm thử)"],
        "data": kw.pop("data", ["Dữ liệu sinh trong test (không cần file ngoài)"]),
        "steps": [("Kiểm tra môi trường tại http://localhost:8080/ và ghi commit đang kiểm thử", "readyz = ready; report có mã commit"),
                  (f"Chạy `{kw.get('cmd_show', test or kw.get('write_test'))}` qua bộ ghi bằng chứng", "pytest báo `passed`, mã thoát 0"),
                  *checks],
        "cmd": kw.pop("cmd", f"{PYTEST} {test}"),
        **kw,
    }


