def it(id_, title, prio, trace, test, goal, checks, c1="Đạt (tự động)", **kw):
    t = ut(id_, title, prio, trace, test, goal, checks, c1=c1, **kw)
    t["data"] = kw.get("data", ["PDF mẫu sinh trong test bằng `tests/fixtures/pdfgen.py`; CSDL PGlite trong bộ nhớ, tạo mới mỗi lần chạy"])
    return t


